pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 depositAmount) public {
        // Restrict to reasonable values
        vm.assume(depositAmount > 0 && depositAmount < 1e30);

        // Store balance before deposit
        uint256 balanceBefore = address(c).balance;

        // Perform deposit
        vm.deal(address(this), depositAmount);
        c.deposit{value: depositAmount}();

        // After deposit, contract balance should increase by exactly depositAmount
        uint256 balanceAfter = address(c).balance;

        // The invariant: balanceAfter == balanceBefore + depositAmount
        assertTrue(balanceAfter == balanceBefore + depositAmount);
    }
}

