// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount1, uint256 amount2) public {
        // Bound amounts to avoid overflow, but keep them nonzero to expose the bug
        amount1 = bound(amount1, 1, 100);
        amount2 = bound(amount2, 1, 100);

        // Initial balance is 0
        assertTrue(address(c).balance == 0);

        // Deposit amount1
        vm.deal(address(this), amount1);
        c.deposit{value: amount1}();

        // Now withdrawAll
        c.withdrawAll();

        // After a successful withdrawal (reference: call returns true, balance reduces, credit resets)
        // The contract balance after withdrawal should be 0 (since we withdrew all)
        // In the mutant, require(!callResult) reverts when call succeeds, so the transaction reverts and state rolls back.
        // Hence the balance remains amount1.
        // But we need to check if the call reverted or not. We'll call again with a second deposit to observe state.
        // Actually simpler: after first deposit and withdraw, try to withdraw again.
        // If the first withdrawal succeeded, balance is 0, credit is 0, so second withdraw does nothing.
        // If the first withdrawal failed (mutant reverted), balance is still amount1, credit is still amount1.
        // So deposit a second amount, then withdraw again. If first succeeded, after second deposit balance = amount2, then withdraw removes it all => final balance 0.
        // If first failed, after second deposit balance = amount1 + amount2, credit[address(this)] = amount1 + amount2, withdraw removes all if call succeeds (but mutant reverts on success) => revert, no change.
        // But we can use try/catch around withdrawAll to detect revert.
        bool reverted = false;
        vm.deal(address(this), amount2);
        c.deposit{value: amount2}();

        try c.withdrawAll() {
            // Withdraw succeeded
        } catch {
            reverted = true;
        }

        // In the reference, after two deposits and a successful withdraw (first might have succeeded if call returns true),
        // Actually the first withdraw might also revert if the call fails... but that's a different scenario.
        // To make a deterministic rule: We'll just check that the balance after deposit and withdrawal is nonnegative and equals the expected sum based on what we withdrew.
        // But since we don't know whether call returns true (depends on receiver), let's assume the receiver (this contract) accepts ETH, so call returns true.
        // Then reference: after first deposit+withdraw, balance=0, credit=0. second deposit adds amount2, second withdraw removes amount2 => balance=0, not reverted.
        // Mutant: first deposit+withdraw reverts (since require(!callResult) reverts when callResult=true), state unchanged: balance=amount1, credit=amount1. second deposit adds amount2 => balance=amount1+amount2, second withdraw also reverts => reverted.
        // So final: reference has reverted=false, mutant has reverted=true. That's the differential.
        assertTrue(reverted == false);
    }
}

