pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 senderSeed) public {
        depositAmount = bound(depositAmount, 1, 1e30);
        address sender = address(uint160(bound(senderSeed, 1, type(uint160).max)));
        vm.deal(sender, depositAmount);
        vm.prank(sender);
        c.deposit{value: depositAmount}();
        uint256 balanceBefore = address(c).balance;
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.withdrawAll.selector));
        // If sender has a valid receiver (non-zero address and not this contract), callResult will be true
        // In reference: withdrawal succeeds -> balance decreases by depositAmount
        // In mutant: require(!callResult) reverts when callResult is true -> balance unchanged
        if (success && balanceBefore > 0) {
            assertTrue(address(c).balance == balanceBefore - depositAmount, "Balance should decrease by deposit amount on successful withdrawal");
        } else {
            // If withdrawal reverted, balance stays same
            assertTrue(address(c).balance == balanceBefore, "Balance unchanged on failed withdrawal");
        }
    }
}

