import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address user, uint depositAmount, uint withdrawAmount) public {
        vm.assume(user != address(0));
        vm.assume(depositAmount > 0 && depositAmount <= type(uint128).max);
        vm.assume(withdrawAmount <= depositAmount);

        // Deposit
        vm.deal(user, depositAmount);
        vm.prank(user);
        c.deposit{value: depositAmount}();

        // Withdraw (partial amount max, but the function only withdraws all credit)
        vm.prank(user);
