    function testFuzz_property(address caller, uint amount) public {
        vm.assume(caller != address(0));
        vm.assume(amount > 0 && amount <= address(this).balance);
        vm.deal(caller, amount);
        vm.prank(caller);
        c.deposit{value: amount}();
        uint balanceBefore = address(c).balance;
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.withdrawAll.selector));
        // The rule: if withdrawAll succeeds, the contract balance decreases by exactly amount;
        // if it reverts, the caller's credit should be zero.
        uint creditAfter;
        if (!success) {
            // If revert, credit must be zero (because the only revert is when callresult fails, but after credit=0)
            // Actually in the buggy version, credit is set to 0 before the require, so after revert credit=0.
            // In reference, credit stays positive if revert. So we check: in reference, after revert credit > 0.
            // But we cannot read credit directly (private). Instead, we assert that if it reverts, 
            // then re-depositing and withdrawing should succeed. Simpler: use a different approach.
            // We use a proxy: try again, if now succeeds, the bug is caught.
        }
        // Simpler rule: after withdrawAll (whether revert or not), the contract balance is <= balanceBefore - amount
        // But reference ensures exact decrease; buggy may decrease even on revert.
        uint balanceAfter = address(c).balance;
        assertTrue(balanceAfter <= balanceBefore - amount || balanceAfter == 0);
    }
